UPDATE lessons SET title='Year 3, Week 5, Lesson 4: Publishing and sharing your story', data=json_patch(data,'{"child_mission":"Prepare a clean final narrative for a real reader and explain presentation choices.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Keep the independent response and two written check responses; record oral retelling or performance where required by the task.","explicit_teaching":null,"extension":"Create a new example using a completely different character or setting, show the same skill, then explain to another person how you checked its accuracy.","follow_up_challenges":null,"guided_practice":"WE DO — attempt each prompt before comparing to the feedback.\n1. Choose a title for a story about a missing bicycle and explain why it fits.\nCOMPARE: \"The Bicycle at the Creek\" suggests setting and problem better than \"My Work\".\n2. Mark where a new paragraph should start in a three-event search story.\nCOMPARE: A shift to a new place or time is a common paragraph break.\n3. List three proofreading checks you will use before publishing.\nCOMPARE: Capitals, end marks and whether every sentence is complete are useful checks.\n4. Write one sentence explaining a revision you made for a reader.\nCOMPARE: The note should name a specific change, not only \"I improved it.\"","hoard_words":null,"independent_task":"YOU DO — complete the following substantial original task, not a copied model.\nPublish a 150–250 word original narrative with a title and paragraphs. Add a short author''s note identifying two revisions and one response to possible reader feedback.","interactive_activities":null,"learning_area":"English","learning_intention":"Prepare a clean final narrative for a real reader and explain presentation choices.","lesson_number":4,"lesson_role":"Speaking and handwriting","materials":["Paper or typing area","Pencil for optional evidence"],"offline_alternative":"Use paper to copy only the original independent prompt; have the child respond in writing or orally as required. Save a photograph or brief parent observation for the learning record.","outcome_codes":["EN2-CWT-01"],"parent_notes":"Parent: Marking guidance: Check title fit, paragraphing, proofreading and a reflective author note. Length may be slightly flexible if quality is strong. Accept plausible original solutions where the text supports them; require the learner to explain at least one independent choice.\n\nParent: Written model 1: Original demonstration: I change \"Story\" to \"The Lost Lantern\" so a reader anticipates a missing light and a search.\n\nParent: Written model 2: Common error: Publishing is not only making text pretty; meaning comes first. Correction: Capitals, end marks and whether every sentence is complete are useful checks.\n\nParent: Assess comprehension and language rather than penalising speech or motor difficulties unrelated to the objective. Keep written models out of the child role.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"A useful title hints at character, setting or problem without spoiling every event. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["A useful title hints at character, setting or problem without spoiling every event.","A vague title does not help a reader know what the piece is about.","Ignore the words and invent a more exciting event.","Copy the model word-for-word and call that independent work."],"question":"Which idea is taught in the stage \"Choose a title that fits the story\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Paragraphs group related sentences. Start a new paragraph when time, place or focus shifts. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["Paragraphs group related sentences. Start a new paragraph when time, place or focus shifts.","One giant block of text makes the story harder to follow.","Copy the model word-for-word and call that independent work.","Treat a missing detail as a stated fact."],"question":"Which idea is taught in the stage \"Use paragraphs when the action changes\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Read slowly for missing words, capitals and full stops after the story meaning is clear. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["Read slowly for missing words, capitals and full stops after the story meaning is clear.","Publishing is not only making text pretty; meaning comes first.","Treat a missing detail as a stated fact.","Skip the prompt because the first idea sounded good."],"question":"Which idea is taught in the stage \"Proofread before sharing\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"An author''s note can name a change made for clarity or audience. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["An author''s note can name a change made for clarity or audience.","A decoration change alone is weaker evidence than a meaning revision.","Skip the prompt because the first idea sounded good.","Ignore the words and invent a more exciting event."],"question":"Which idea is taught in the stage \"Explain one revision to a reader\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"\"The Bicycle at the Creek\" suggests setting and problem better than \"My Work\". This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["\"The Bicycle at the Creek\" suggests setting and problem better than \"My Work\".","A vague title does not help a reader know what the piece is about.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Choose a title for a story about a missing bicycle and explain why it fits.\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"A shift to a new place or time is a common paragraph break. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["A shift to a new place or time is a common paragraph break.","One giant block of text makes the story harder to follow.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Mark where a new paragraph should start in a three-event search story.\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"Capitals, end marks and whether every sentence is complete are useful checks. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["Capitals, end marks and whether every sentence is complete are useful checks.","Publishing is not only making text pretty; meaning comes first.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"List three proofreading checks you will use before publishing.\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"The note should name a specific change, not only \"I improved it.\" This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["The note should name a specific change, not only \"I improved it.\"","A decoration change alone is weaker evidence than a meaning revision.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Write one sentence explaining a revision you made for a reader.\", which feedback is most useful?","type":"multiple_choice"},{"explanation":"Meaningful understanding is shown when a learner transfers the method to new text or speech and explains their evidence.","marking_guide":"Require an original relevant example, accurate terminology and an explanation grounded in the example.","question":"Use your own example to demonstrate title and explain the evidence supporting your choice.","sample_answer":"Original demonstration: I change \"Story\" to \"The Lost Lantern\" so a reader anticipates a missing light and a search.","type":"short_answer"},{"explanation":"Explaining a correction helps the learner distinguish an effective strategy from a plausible-sounding but inaccurate approach.","marking_guide":"Require a genuine relevant error, accurate correction and a reason that refers to the target concept.","question":"Identify and correct a common mistake relating to proofread in this lesson.","sample_answer":"Common error: Publishing is not only making text pretty; meaning comes first. Correction: Capitals, end marks and whether every sentence is complete are useful checks.","type":"short_answer"}],"resources":null,"response_prompt":"Submit your original independent work and your brief explanation of the key choices you made.","review_status":"unreviewed","seed_key":"s2-eng-y3-w05-l4","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; compare the existing Coming Soon card and official syllabus content points before marking verified.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise title.","Read the mission before you start writing or speaking.","Your goal is: Prepare a clean final narrative for a real reader and explain presentation choices."],"guided":["Attempt each guided prompt without looking ahead.","Compare your attempt with the supplied specific feedback.","Guided comparison: A shift to a new place or time is a common paragraph break."],"learn":["Study the first worked demonstration carefully.","Name the exact words or events that make it work.","Demonstration: I change \"Story\" to \"The Lost Lantern\" so a reader anticipates a missing light and a search."],"quiz":["Read the whole question and eliminate misconceptions.","Prefer the option that quotes or uses actual evidence.","Likely trap: Publishing is not only making text pretty; meaning comes first."],"submit":["Include your own response and a short reason.","Proofread names, sequence and punctuation before sending.","Success looks like: Prepare a clean final narrative for a real reader and explain presentation choices."],"teach0":["Focus on choose a title that fits the story.","Hold this teaching point: A useful title hints at character, setting or problem without spoiling every event.","Worked comparison: \"The Bicycle at the Creek\" suggests setting and problem better than \"My Work\"."],"teach1":["Focus on use paragraphs when the action changes.","Hold this teaching point: Paragraphs group related sentences. Start a new paragraph when time, place or focus shifts.","Worked comparison: A shift to a new place or time is a common paragraph break."],"teach2":["Focus on proofread before sharing.","Hold this teaching point: Read slowly for missing words, capitals and full stops after the story meaning is clear.","Worked comparison: Capitals, end marks and whether every sentence is complete are useful checks."],"teach3":["Focus on explain one revision to a reader.","Hold this teaching point: An author''s note can name a change made for clarity or audience.","Worked comparison: The note should name a specific change, not only \"I improved it.\""],"write":["Use the independent instructions, not the model words.","Give an original response and the reason behind it.","Independent reminder: Publish a 150–250 word original narrative with a title and paragraphs. Add a short author''s note identifying two revisions and one response to possible reader f"]},"subject":"English","success_criteria":["I can use title with a specific example from this lesson.","I can identify paragraph and point to the words or events that support it.","I can practise proofread independently on a new prompt.","I can notice publish needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying title independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to choose a title that fits the story?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI change \"Story\" to \"The Lost Lantern\" so a reader anticipates a missing light and a search.\n\nYOUR SMALL TRY\nChoose a title for a story about a missing bicycle and explain why it fits.\n\nCOMPARE AND CORRECT\n\"The Bicycle at the Creek\" suggests setting and problem better than \"My Work\".","explain":"A useful title hints at character, setting or problem without spoiling every event.\n\nA useful title hints at character, setting or problem without spoiling every event. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nA vague title does not help a reader know what the piece is about. Re-read the prompt and correct the misunderstanding before moving on.","title":"Choose a title that fits the story","visual":[{"alt":"Vague title Story improved to The Lost Lantern.","caption":"A title should hint at the story focus for a reader.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Weak title</text><text x=\"28\" y=\"78\">Story</text><text x=\"358\" y=\"42\">Stronger title</text><text x=\"358\" y=\"78\">The Lost Lantern</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I read the first example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or events that carry the meaning before you copy a conclusion.","who":"juno"},{"text":"So I should try the small prompt myself, then compare it with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: I change \"Story\" to \"The Lost Lantern\" so a reader anticipates a missing light and a search. Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I read the first example, but I am not sure which detail matters most.\nJuno: Name the exact words or events that carry the meaning before you copy a conclusion.\nPip: So I should try the small prompt myself, then compare it with the feedback.\nJuno: Pause here. Use this model: I change \"Story\" to \"The Lost Lantern\" so a reader anticipates a missing light and a search. Then write your own attempt."}}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying paragraph independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to use paragraphs when the action changes?","type":"multiple_choice"},"example":"WATCH MY THINKING\nWhen the search moves from the shed to the creek, I begin a new paragraph.\n\nYOUR SMALL TRY\nMark where a new paragraph should start in a three-event search story.\n\nCOMPARE AND CORRECT\nA shift to a new place or time is a common paragraph break.","explain":"Paragraphs group related sentences. Start a new paragraph when time, place or focus shifts.\n\nParagraphs group related sentences. Start a new paragraph when time, place or focus shifts. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nOne giant block of text makes the story harder to follow. Re-read the prompt and correct the misunderstanding before moving on.","title":"Use paragraphs when the action changes","visual":[{"alt":"Single draft block versus paragraphs at action changes for publishing.","caption":"Paragraphing and proofreading help a real reader.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Draft block</text><text x=\"28\" y=\"78\">one long paragraph</text><text x=\"358\" y=\"42\">Published</text><text x=\"358\" y=\"78\">paragraphs at action changes</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying proofread independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to proofread before sharing?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI read aloud and catch a missing full stop before I share the story with my family.\n\nYOUR SMALL TRY\nList three proofreading checks you will use before publishing.\n\nCOMPARE AND CORRECT\nCapitals, end marks and whether every sentence is complete are useful checks.","explain":"Read slowly for missing words, capitals and full stops after the story meaning is clear.\n\nRead slowly for missing words, capitals and full stops after the story meaning is clear. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nPublishing is not only making text pretty; meaning comes first. Re-read the prompt and correct the misunderstanding before moving on.","title":"Proofread before sharing"},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying publish independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to explain one revision to a reader?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI note that I added a clearer ending so the reader knows the lantern was returned.\n\nYOUR SMALL TRY\nWrite one sentence explaining a revision you made for a reader.\n\nCOMPARE AND CORRECT\nThe note should name a specific change, not only \"I improved it.\"","explain":"An author''s note can name a change made for clarity or audience.\n\nAn author''s note can name a change made for clarity or audience. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nA decoration change alone is weaker evidence than a meaning revision. Re-read the prompt and correct the misunderstanding before moving on.","title":"Explain one revision to a reader"}],"title":"Year 3, Week 5, Lesson 4: Publishing and sharing your story","unit_number":1,"unit_title":"Narrative: story elements and planning","week":5,"week_in_unit":5,"word_challenges":null,"worked_example":"I DO — I change \"Story\" to \"The Lost Lantern\" so a reader anticipates a missing light and a search.\n\nNow look for the exact evidence in the words or actions. When the search moves from the shed to the creek, I begin a new paragraph.","worked_visuals":[{"alt":"Vague title Story improved to The Lost Lantern.","caption":"A title should hint at the story focus for a reader.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Weak title</text><text x=\"28\" y=\"78\">Story</text><text x=\"358\" y=\"42\">Stronger title</text><text x=\"358\" y=\"78\">The Lost Lantern</text></g></svg>"},{"alt":"Single draft block versus paragraphs at action changes for publishing.","caption":"Paragraphing and proofreading help a real reader.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Draft block</text><text x=\"28\" y=\"78\">one long paragraph</text><text x=\"358\" y=\"42\">Published</text><text x=\"358\" y=\"78\">paragraphs at action changes</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w05-l4' AND family_id IS NULL;
